
import pymysql
from password_masking.password_utilis import encrypt_password, decrypt_password

# Paste the encrypted token generated by encrypt_once.py
ENCRYPTED_PASSWORD = b"gAAAAABq33DC0aPb0tHmFhkICU8hdV9uVe1KjmqhMc9Ynzz0qqZSlWZkNNbIE9Q7vst2e9tsNx9lyBv1Oxu7n8ei0O1QPvk7XA=="


def main():
    connection = None

    try:
        # Decrypt the password
        password = decrypt_password(ENCRYPTED_PASSWORD)

        # Connect to MySQL
        connection = pymysql.connect(
            host="localhost",
            user="root",
            password=str.__str__(password),
            database="testdb",
            cursorclass=pymysql.cursors.DictCursor
        )

        print("Connected to MySQL successfully!")

        with connection.cursor() as cursor:

            # Create table
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS employees1 (
                    id INT AUTO_INCREMENT PRIMARY KEY,
                    name VARCHAR(100),
                    department VARCHAR(100)
                )
            """)

            # Insert records
            insert_query = """
                INSERT INTO employees1 (name, department)
                VALUES (%s, %s)
            """

            values = [
                ("John", "IT"),
                ("Riyas", "DS"),
                ("Ajim", "Support"),
                ("Asiga", "HR")
            ]

            cursor.executemany(insert_query, values)
            connection.commit()

            # Retrieve records
            cursor.execute("SELECT * FROM employees1")
            result = cursor.fetchall()

            # Save records to a text file
            with open("employees1_output.txt", "w", encoding="utf-8") as file:
                for row in result:
                    file.write(
                        f"{row['id']} - {row['name']} - "
                        f"{row['department']}\n"
                    )

        print("Employee records saved to employees1_output.txt")

    except Exception as error:
        print("Error:", error)

    finally:
        if connection is not None:
            connection.close()
            print("MySQL connection closed.")


if __name__ == "__main__":
    main()
